// A CommonJS package: functions, a class, errors, callbacks and promises.
"use strict";
const util = require("./util");

exports.add = (a, b) => a + b;
exports.sum = (xs) => xs.reduce((s, x) => s + x, 0);
exports.describe = (o) => Object.keys(o).sort().map((k) => `${k}=${JSON.stringify(o[k])}`).join(",");
exports.twice = (f, x) => f(f(x));
exports.mapAll = (xs, f) => xs.map((x, i) => f(x, i));
exports.fail = (msg) => { throw new RangeError(msg); };
exports.failWith = (v) => { throw v; };
exports.later = (v) => new Promise((resolve) => setTimeout(() => resolve(v * 2), 1));
exports.rejectLater = (msg) => Promise.reject(new TypeError(msg));
exports.point = (x, y) => ({ x, y, tags: ["a", "b"], nested: { ok: true } });
exports.nothing = () => null;
exports.PI = util.round(Math.PI, 2);
class Counter {
  constructor(start) { this.n = start; }
  inc() { this.n += 1; return this; }
  get value() { return this.n; }
}
exports.Counter = Counter;
exports.after = (ms, f) => { setTimeout(f, ms); };
